// Builds the Claude request from the redacted findings (system-check-issues.py, ADR 007).
const body = $input.item.json.body ?? $input.item.json;
const findings = Array.isArray(body.findings) ? body.findings : [];
const request = {
  model: 'claude-haiku-5-5',
  max_tokens: 8000,
  output_config: { effort: 'low', format: { type: 'json_schema', schema: {"type": "object", "additionalProperties": false, "required": ["assessment", "findings", "telegram_summary"], "properties": {"assessment": {"type": "string"}, "telegram_summary": {"type": "string"}, "findings": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["fingerprint", "issue_body"], "properties": {"fingerprint": {"type": "string"}, "issue_body": {"type": "string"}}}}}} } },
  system: "Du bist der Pr\u00fcfer f\u00fcr den w\u00f6chentlichen Systemcheck eines privaten Homelabs (ein Debian-Host mit rund 36 Docker-Diensten, Secrets in HashiCorp Vault, Traefik, Kestra, Gitea).\nDu bekommst eine Liste von Befunden. Ein Skript hat sie nach festen Regeln ermittelt; die Daten sind bereinigt (Platzhalter wie <host>, <internal-ip>, <user>, <redacted>).\n\nRegeln:\n- Bearbeite genau die gelieferten Befunde. Erfinde keine neuen, lass keinen weg, \u00e4ndere keinen Schweregrad und keinen Fingerprint.\n- Schreibe Deutsch, sachlich und knapp. Keine Floskeln.\n- Wiederhole keine Werte, die wie Passw\u00f6rter, Tokens oder Schl\u00fcssel aussehen, und versuche nicht, Platzhalter aufzul\u00f6sen.\n- issue_body: Markdown mit genau drei kurzen Abschnitten: \"**Was ist los**\" (1-2 S\u00e4tze), \"**M\u00f6gliche Ursache**\" (1-3 Stichpunkte, als Vermutung gekennzeichnet), \"**N\u00e4chste Schritte**\" (1-4 nummerierte, konkrete Schritte, gern mit Befehl in Backticks). Keine \u00dcberschrift mit #.\n- assessment: 1-3 S\u00e4tze Gesamtbild (was ist dringend, was kann warten).\n- telegram_summary: 2-4 Zeilen reiner Text ohne Markdown, das Wichtigste zuerst.",
  messages: [{
    role: 'user',
    content: 'Systemcheck vom ' + (body.date || '?') + '. Befunde (JSON):\n' + JSON.stringify(findings, null, 1),
  }],
};
return [{ json: { request, fingerprints: findings.map(f => f.fingerprint) } }];

// Validates Claude's answer; ok:false -> Kestra uses its template (nothing is lost).
const res = $input.item.json;
const expected = $('Anfrage bauen').item.json.fingerprints;
const fail = (reason) => [{ json: { ok: false, reason } }];
if (res.stop_reason !== 'end_turn') return fail('stop_reason ' + res.stop_reason);
// Haiku 5.5 thinks by default: the content starts with a thinking block, the JSON is in the text block
const text = (res.content || []).find(b => b.type === 'text');
if (!text) return fail('kein Text in der Antwort');
let out;
try { out = JSON.parse(text.text); } catch (e) { return fail('kein gültiges JSON'); }
// Only texts for fingerprints that were sent; Claude must not add findings
const findings = (out.findings || []).filter(f => expected.includes(f.fingerprint));
return [{ json: { ok: true, assessment: out.assessment || '', telegram_summary: out.telegram_summary || '',
                  findings, model: res.model, usage: res.usage } }];
